import { describe, test, expect } from "vitest";
import mri from "../lib/index.js";

describe("Boolean defaults leak into _ (mri) - invariant tests", () => {
  describe("Core bug fix: boolean flags should not leak numeric values into _", () => {
    test("boolean flag followed by numeric string (short flag)", () => {
      const res = mri(["-t", "3"], { boolean: "t" });
      expect(res.t).toBe(true);
      expect(res._).toEqual(["3"]);
      expect(typeof res._[0]).toBe("string");
    });

    test("boolean flag followed by large numeric string (long flag)", () => {
