import { describe, test, expect } from "vitest";
import mri from "../lib/index.js";

describe("Boolean defaults leak into _ (mri) - invariant tests", () => {
  describe("Core bug fix: boolean flags should not leak numeric values into _", () => {
    test("boolean flag followed by numeric string (short flag)", () => {
      const res = mri(["-t", "3"], { boolean: "t" });
      expect(res.t).toBe(true);
      expect(res._).toEqual(["3"]);
      expect(typeof res._[0]).toBe("string");
    });

    test("boolean flag followed by large numeric string (long flag)", () => {
      const res = mri(["--verbose", "999999"], { boolean: "verbose" });
      expect(res.verbose).toBe(true);
      expect(res._).toEqual(["999999"]);
      expect(typeof res._[0]).toBe("string");
    });

    test("boolean flag followed by zero", () => {
      const res = mri(["-v", "0"], { boolean: "v" });
      expect(res.v).toBe(true);
      expect(res._).toEqual(["0"]);
      expect(typeof res._[0]).toBe("string");
    });

    test("boolean flag followed by float", () => {
      const res = mri(["-v", "3.14"], { boolean: "v" });
      expect(res.v).toBe(true);
      expect(res._).toEqual(["3.14"]);
      expect(typeof res._[0]).toBe("string");
    });
  });

  describe("Boolean defaults should not cause numeric leak", () => {
    test("default boolean true with numeric arg", () => {
      const res = mri(["-v", "42"], { default: { v: true } });
      expect(res.v).toBe(true);
      expect(res._).toEqual(["42"]);
      expect(typeof res._[0]).toBe("string");
    });

    test("default boolean false with numeric arg", () => {
      const res = mri(["-v", "42"], { default: { v: false } });
      expect(res.v).toBe(true); // flag provided, so it's true
      expect(res._).toEqual(["42"]);
      expect(typeof res._[0]).toBe("string");
    });

    test("multiple boolean defaults with numeric args", () => {
      const res = mri(["-a", "1", "-b", "2"], { default: { a: true, b: true } });
      expect(res.a).toBe(true);
      expect(res.b).toBe(true);
      expect(res._).toEqual(["1", "2"]);
      expect(res._.every(v => typeof v === "string")).toBe(true);
    });
  });

  describe("Edge cases: boolean value parsing", () => {
    test("explicit --flag=true", () => {
      const res = mri(["--verbose=true"], { boolean: "verbose" });
      expect(res.verbose).toBe(true);
      expect(res._).toEqual([]);
    });

    test("explicit --flag=false", () => {
      const res = mri(["--verbose=false"], { boolean: "verbose" });
      expect(res.verbose).toBe(false);
      expect(res._).toEqual([]);
    });

    test("explicit --no-flag", () => {
      const res = mri(["--no-verbose"], { boolean: "verbose" });
      expect(res.verbose).toBe(false);
      expect(res._).toEqual([]);
    });

    test("boolean flag with explicit =value (non-boolean string)", () => {
      const res = mri(["--verbose=hello"], { boolean: "verbose" });
      expect(res.verbose).toBe(true);
      expect(res._).toEqual(["hello"]);
    });
  });

  describe("Multiple boolean flags", () => {
    test("multiple boolean flags in sequence", () => {
      const res = mri(["-a", "-b", "-c"]);
      expect(res).toEqual({ _: [], a: true, b: true, c: true });
    });

    test("multiple boolean flags with trailing positional args", () => {
      const res = mri(["-a", "-b", "foo", "bar"]);
      expect(res).toEqual({ _: ["foo", "bar"], a: true, b: true });
    });

    test("bundled boolean flags", () => {
      const res = mri(["-abc"]);
      expect(res).toEqual({ _: [], a: true, b: true, c: true });
    });

    test("bundled flags with trailing value consumed by last", () => {
      const res = mri(["-abc", "val"]);
      expect(res).toEqual({ _: ["val"], a: true, b: true, c: true });
    });
  });

  describe("Concurrent and async ordering invariants", () => {
    test("parsing is deterministic", () => {
      const args = ["-v", "42", "--name", "test", "-x"];
      const opts = { default: { v: true }, boolean: "x" };

      const results = Array.from({ length: 100 }, () => mri([...args], { ...opts }));
      const first = JSON.stringify(results[0]);

      expect(results.every(r => JSON.stringify(r) === first)).toBe(true);
    });

    test("empty args always returns same structure", () => {
      const results = Array.from({ length: 50 }, () => mri([], { default: { v: true } }));

      expect(results.every(r => 
        r._.length === 0 && r.v === true
      )).toBe(true);
    });
  });

  describe("Boundary conditions", () => {
    test("null args", () => {
      const res = mri(null);
      expect(res).toEqual({ _: [] });
    });

    test("undefined args", () => {
      const res = mri(undefined);
      expect(res).toEqual({ _: [] });
    });

    test("empty args array", () => {
      const res = mri([]);
      expect(res).toEqual({ _: [] });
    });

    test("args with --", () => {
      const res = mri(["--", "--not-a-flag"]);
      expect(res._).toEqual(["--not-a-flag"]);
    });

    test("args with -- and nothing after", () => {
      const res = mri(["--"]);
      expect(res._).toEqual([]);
    });

    test("many positional args", () => {
      const args = Array.from({ length: 1000 }, (_, i) => `arg${i}`);
      const res = mri(args);
      expect(res._.length).toBe(1000);
    });
  });

  describe("Type coercion invariants", () => {
    test("number coercion for non-boolean, non-string options", () => {
      const res = mri(["--count", "42"]);
      expect(res.count).toBe(42);
      expect(typeof res.count).toBe("number");
    });

    test("string option preserves leading zeros", () => {
      const res = mri(["--id", "007"], { string: "id" });
      expect(res.id).toBe("007");
      expect(typeof res.id).toBe("string");
    });

    test("zero is coerced to number", () => {
      const res = mri(["--val", "0"]);
      expect(res.val).toBe(0);
      expect(typeof res.val).toBe("number");
    });

    test("float is coerced", () => {
      const res = mri(["--val", "3.14"]);
      expect(res.val).toBe(3.14);
      expect(typeof res.val).toBe("number");
    });
  });

  describe("Alias interactions", () => {
    test("boolean alias works correctly", () => {
      const res = mri(["-v", "42"], { boolean: "verbose", alias: { verbose: "v" } });
      expect(res.verbose).toBe(true);
      expect(res.v).toBe(true);
      expect(res._).toEqual(["42"]);
      expect(typeof res._[0]).toBe("string");
    });
  });
});

